/// <summary>
/// Data contract for the <c>AAXProdOrderScheduledBusinessEvent</c> business event.
/// </summary>
[DataContract]
public final class AAXProdOrderScheduledBusinessEventContract extends BusinessEventsContract
{
    private DataAreaId legalEntity;
    private ProdId productionOrderId;
    private ItemId itemId;
    private str itemName;
    private int productionStatus;

}

