/// <summary>
/// Creates a new <c>AAXProdOrderScheduledBusinessEventContract</c> from the specified <c>ProdTable</c> record.
/// </summary>
/// <param name="_prodTable">The source ProdTable record.</param>
/// <returns>A new populated instance of <c>AAXProdOrderScheduledBusinessEventContract</c>.</returns>
public static AAXProdOrderScheduledBusinessEventContract newFromProdTable(ProdTable _prodTable)
{
    var contract = new AAXProdOrderScheduledBusinessEventContract();
    contract.initialize(_prodTable);

    return contract;
}

/// <summary>
/// Initializes the contract fields from the source record.
/// </summary>
/// <param name="_prodTable">The source ProdTable record.</param>
private void initialize(ProdTable _prodTable)
{
    legalEntity = _prodTable.DataAreaId;
    productionOrderId = _prodTable.ProdId;
    itemId = _prodTable.ItemId;
    itemName = InventTable::find(_prodTable.ItemId).NameAlias;
    productionStatus = enum2int(_prodTable.ProdStatus);
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
